"use strict";
// Each function returns an object literal whose JavaScript-inferred type
// lacks members that index.d.ts promises.

// An index signature over a literal built empty, then assigned.
function settings() {
  const out = {};
  out.size = "12px";
  out.family = "serif";
  return out;
}

// An index signature over a literal with fixed keys.
function counts() {
  return { lines: 3, words: 12 };
}

// An expando on a non-empty literal: the checker's literal type has no `max`.
function stats(xs) {
  const out = { count: xs.length, sum: 0 };
  for (const x of xs) out.sum += x;
  out.max = Math.max(...xs);
  return out;
}

// An index signature whose values are a declared interface.
function fonts() {
  return { body: { name: "serif" }, code: { name: "mono" } };
}

exports.settings = settings;
exports.counts = counts;
exports.stats = stats;
exports.fonts = fonts;
